-- 217: Rights clean-up found by the audit of the Curriculum Repositories (lab_manager docs/design-notes/curriculum-repository-audit-2026-11-02.md).
--
-- 1. 20 timeline events kept quotations of news, advocacy and encyclopedia pages at the excerpt-only tier without a rights note. Dustin chose
--    (2026-11-02) to keep a summary in our own words: the description is replaced by a paraphrase and the record moves to summary-only.
-- 2. 5 coherence findings hold excerptText (short quotations of documents). The excerpt text goes and the object tier becomes summary-only.
-- 3. 9 cite-only mandate records still hold statementTextEn, the English translation of the official wording. The field goes.
-- 4. 2 test rows (source_repo diagnostic-test) are deleted.
-- Each statement is guarded, so running this twice changes nothing. Generated by scripts/generate_rights_cleanup_migration.py.
SET search_path = public, extensions;

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('Sen. Ronda Storms (R-Valrico) introduced SB 2692, modeled on the Discovery Institute''s template statute, the Academic Freedom Act. Rep. Alan Hays introduced the House companion HB 1483, narrowed to call for evolutionary theory to be presented thoroughly and analyzed critically. John Stemberger (Florida Family Policy Council) was the lead public advocate. Hays hosted a closed March 2008 press event with a Discovery Institute representative, open to legislators only. The House passed its substituted version (HB 1483 text swapped into SB 2692) 71-43 on April 28, 2008. The Senate rejected the substitution and restored its own text, sending it back to the House, which left it untouched, so the bill died at the end of the session without becoming law. The same Discovery Institute template was later enacted in Louisiana (June 2008) and Tennessee (2012), but Florida''s version did not pass.'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'florida-lpm' AND source_record_id = 'FLLP-EVENT-sb2692-hb1483-2008-academic-freedom-act' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('In summer 2024, FLDOE asked publishers submitting science textbooks for state adoption to reduce or remove climate-change content, and the publishers complied. Teachers said this created a climate of wariness that discouraged classroom discussion of climate topics, and some cited fear of professional retaliation. It ran through the ordinary textbook-adoption review process (the same process HB 989 opened to resident challenges in 2017). It was not a formal standards rewrite, and it was reported publicly only in 2026, through a joint investigation.'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'florida-lpm' AND source_record_id = 'FLLP-EVENT-2024-textbook-climate-content-removal' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('FLDOE released its draft K-12 science standards rewrite for public comment. Reporting found that the word evolution appears nowhere in the proposed high-school life-science standards, and that the terms climate change and global warming appear nowhere in the draft. The draft does keep weather and climate, climate systems, and climate impacts on biodiversity. It contains roughly 1,000 high-school science benchmarks and is not built on the National Research Council''s 2012 Framework for K-12 Science Education, the NGSS-aligned framework most other states now use. Public comment was accepted via fldoe.org/standardsreview/.'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'florida-lpm' AND source_record_id = 'FLLP-EVENT-2026-draft-standards-released-for-comment' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('First in-person public listening session on the draft 2026 science standards, held at Armwood High School, Seffner (Hillsborough County). Florida Phoenix described the parents and teachers present as stunned. FLDOE Senior Education Manager Patricia Duncan told attendees that the omissions were unintentional and that the listening tour was only the opening stage of a longer process.'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'florida-lpm' AND source_record_id = 'FLLP-EVENT-2026-listening-tour-armwood-hs' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('The Dover Area School Board curriculum committee, chaired by William Buckingham, began pushing to balance evolution teaching with creationism during discussions of adopting Kenneth Miller and Joseph Levine''s textbook Biology. Buckingham objected that the book promoted Darwinism too heavily.'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'pennsylvania-lpm' AND source_record_id = 'PALP-EVENT-dover-curriculum-committee-pushes-balance' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('All eight Dover High School science teachers sent the superintendent a letter stating that intelligent design is neither science nor a theory accepted by scientists. They asked to be excused from reading the disclaimer because reading it would conflict with their professional ethics. They formally refused on Jan 6, 2005, and the administration agreed on Jan 7 that administrators would read it instead. The assistant superintendent first read the disclaimer on Jan 18, 2005, in each 9th-grade biology classroom, and roughly 15 students walked out during the reading.'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'pennsylvania-lpm' AND source_record_id = 'PALP-EVENT-dover-teachers-refuse-and-disclaimer-first-read' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('All eight Republican incumbents who had supported the intelligent-design policy were defeated by the Dover CARES slate: Bernadette Reinking, Terry Emig, Bryan Rehm (also a named plaintiff in the lawsuit), Herbert (Rob) McIlvaine, Judy McIlvaine, Larry Gurreri, Patricia Dapp and Phil Herman. The ousted incumbents included board president Sheila Harkins and former board president Alan Bonsell. The new board said it would drop the policy whatever the pending court ruling turned out to be.'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'pennsylvania-lpm' AND source_record_id = 'PALP-EVENT-dover-2005-election' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('The Dover Area School Board voted 6-3 to amend the biology curriculum so that students would learn about weaknesses in Darwin''s theory and about alternative accounts of evolution, intelligent design among them. FOR: Alan Bonsell, William Buckingham, Jane Cleaver, Heather Geesey, Sheila Harkins, Angie Ziegler-Yingling. AGAINST: Jeffrey Brown, Carol (Casey) Brown, Noel Wenrich. Jeff and Casey Brown, a married couple who had served on the board for 5 and 10 years respectively, resigned in protest at the end of the same meeting. Casey Brown said it had become clear that the board''s new direction made holding a particular religious belief the top priority, and that she could no longer serve effectively as a member.'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'pennsylvania-lpm' AND source_record_id = 'PALP-EVENT-dover-2004-10-18-board-vote' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('The newly elected Dover CARES board voted unanimously, by voice vote and with no discussion, to formally rescind the intelligent-design policy.'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'pennsylvania-lpm' AND source_record_id = 'PALP-EVENT-dover-2006-01-policy-rescinded' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('Six weeks of testimony in Harrisburg, PA, before Judge John E. Jones III (US District Court, Middle District of Pennsylvania; a George W. Bush appointee). Plaintiffs'' expert witnesses included Kenneth R. Miller (Brown University), Barbara Forrest (SE Louisiana University, who testified on the cdesign proponentsists find-and-replace artifact in draft manuscripts of Of Pandas and People), Kevin Padian, Robert Pennock, John Haught and Brian Alters. Defense expert witnesses Michael Behe (Lehigh University) and Scott Minnich (University of Idaho) testified on irreducible complexity, the bacterial flagellum argument. Three other Discovery-Institute-affiliated experts (William Dembski, Stephen Meyer, John Angus Campbell) had withdrawn before depositions.'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'pennsylvania-lpm' AND source_record_id = 'PALP-EVENT-kitzmiller-trial' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('The $11 reflects a $1 nominal-damages award to each of the 11 plaintiffs, plus $1,000,000 toward fees and costs. The plaintiffs'' documented fees and expenses totaled $2,067,226. Pepper Hamilton, which handled the case pro bono, billed only about $267,000 in hard costs and no attorney time. The remainder was split between Americans United and the ACLU of Pennsylvania as reimbursement of their own costs.'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'pennsylvania-lpm' AND source_record_id = 'PALP-EVENT-dover-2006-02-legal-fees-settlement' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('The ACLU''s newspaper advertisement (reported in the Chattanooga Times) offered to defend any Tennessee teacher willing to test the Butler Act. George Rappleyea, a Dayton engineer and civic booster, convinced a group of Dayton businessmen at Robinson''s Drug Store to recruit John T. Scopes, a local substitute teacher and football coach, as the test defendant, explicitly to generate publicity and business for the town.'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'tennessee-lpm' AND source_record_id = 'TNLP-EVENT-aclu-ad-and-scopes-recruitment' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('Within three days of Gary Scott''s lawsuit being filed, a repeal bill (House Bill No. 48, Chapter No. 237) passed both chambers of the Tennessee legislature on May 13, 1967. Governor Buford Ellington signed it (sources disagree on the exact day, May 17 or 18). The repeal took effect September 1, 1967, roughly 18 months before the US Supreme Court decided Epperson v. Arkansas (Nov 12, 1968) and struck down a near-identical Arkansas law. The Scott controversy drove the Tennessee repeal independently of Epperson.'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'tennessee-lpm' AND source_record_id = 'TNLP-EVENT-butler-act-repealed' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('Senate Bill 394 / House Bill 597, enacted as Chapter 377 of the 1973 Public Acts. It was sponsored by Sen. Milton H. Hamilton, with House backing from Speaker Ned McWherter and Rep. Tommy Bennett, and championed by Rep. Bill Carter of Rhea County (home of the original Scopes trial). Carter said that because he had unsuccessfully opposed repeal of the Evolution Law, he felt duty bound to do everything in his power to get this bill passed. The act required biology textbooks that treat human origins to give other theories, the biblical Genesis account among them, equal space and emphasis. It also required that evolution carry a disclaimer that it was not to be taken as scientific fact. The statute applied no such disclaimer to the Bible, which it defined as a reference work. Governor Winfield Dunn signed it.'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'tennessee-lpm' AND source_record_id = 'TNLP-EVENT-tn-1973-equal-time-law-passed' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('HB 368 (Rep. Bill Dunn) passed the House 70-23 on April 7, 2011. SB 893 (Sen. Bo Watson) stalled in Senate committee through 2011 and was revived March 7, 2012. It cleared the Senate Education Committee 7-1 on March 14, after an amendment that referred to subjects that may provoke debate and dispute, and passed the full Senate 24-8 on March 20, 2012. It was transmitted to Governor Bill Haslam March 29, 2012.'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'tennessee-lpm' AND source_record_id = 'TNLP-EVENT-tn-2011-2012-teacher-protection-act-legislative-process' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('Rhea County Courthouse, Dayton, Tennessee. Judge John T. Raulston. Prosecution: District Attorney Tom Stewart, Herbert E. Hicks, Sue K. Hicks and Gordon McKenzie, joined by William Jennings Bryan. Defense: Clarence Darrow (lead), Arthur Garfield Hays (ACLU), Dudley Field Malone, John R. Neal, W.O. Thompson and F.B. McElwee. On day 7, with the jury excused, Darrow called Bryan to the stand to question his literal reading of the Bible. Asked where Cain found his wife, Bryan replied that finding her was a job for the agnostics. The exchange is generally seen as having damaged Bryan''s credibility, even though Raulston struck the testimony the next day. Scopes was found guilty and fined $100. The judge set the fine rather than the jury, which became the basis of the 1927 reversal. H.L. Mencken''s Baltimore Sun coverage coined the label Monkey Trial, and this was the first American trial broadcast live nationally by radio (Chicago''s WGN).'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'tennessee-lpm' AND source_record_id = 'TNLP-EVENT-scopes-trial' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('After House passage 71-5 (Jan 28) and Senate passage 24-6 (Mar 13), Governor Austin Peay signed the Butler Act. Peay said nothing important in the books then used in Tennessee schools would conflict with it. He also said the people had a right to control what their schools teach, and that he did not expect the law ever to be enforced.'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'tennessee-lpm' AND source_record_id = 'TNLP-EVENT-butler-act-signed' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('It was the first bill of his term that Haslam handled this way. He said he did not believe the law changed the science curriculum or allowed anything not already allowed. He judged, however, that the bill fell short of the clarity good legislation should provide, and that this was his concern. Tennessee was the second state (after Louisiana, 2008) to pass this type of law. Codified at T.C.A. S49-6-1030.'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'tennessee-lpm' AND source_record_id = 'TNLP-EVENT-haslam-lets-teacher-protection-act-become-law' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('Bryan died in his sleep (reported stroke) in Dayton, Tennessee, after church and an afternoon nap. H.L. Mencken privately remarked, in coarse terms, that he and others had killed Bryan. Mencken''s published obituary (Baltimore Evening Sun, July 27) was openly hostile and called Bryan vulgar and common.'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'tennessee-lpm' AND source_record_id = 'TNLP-EVENT-bryan-death' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(jsonb_set(content, '{description}', to_jsonb('Rep. John Washington Butler introduced House Bill No. 185. It made it unlawful for any teacher in a state-funded Tennessee school or university to teach a theory that contradicted the Bible''s account of how humans came to exist and held instead that humans descended from lower animals. The penalty was a misdemeanor fine of $100 to $500 per offense.'::text)), '{accessTier}', '"summary-only"'),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'tennessee-lpm' AND source_record_id = 'TNLP-EVENT-butler-act-introduced' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(content, '{objects}', (SELECT jsonb_agg((t.o - 'excerptText') || '{"accessTier": "summary-only"}'::jsonb ORDER BY t.n) FROM jsonb_array_elements(content -> 'objects') WITH ORDINALITY AS t(o, n))),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'pennsylvania-lpm' AND source_record_id = 'PALP-FINDING-dover-policy-exceeded-state-standard' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(content, '{objects}', (SELECT jsonb_agg((t.o - 'excerptText') || '{"accessTier": "summary-only"}'::jsonb ORDER BY t.n) FROM jsonb_array_elements(content -> 'objects') WITH ORDINALITY AS t(o, n))),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'pennsylvania-lpm' AND source_record_id = 'PALP-FINDING-pa-2002-proposed-vs-final-wording-change' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(content, '{objects}', (SELECT jsonb_agg((t.o - 'excerptText') || '{"accessTier": "summary-only"}'::jsonb ORDER BY t.n) FROM jsonb_array_elements(content -> 'objects') WITH ORDINALITY AS t(o, n))),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'tennessee-lpm' AND source_record_id = 'TNLP-FINDING-1973-law-vs-2012-law-framing-shift' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(content, '{objects}', (SELECT jsonb_agg((t.o - 'excerptText') || '{"accessTier": "summary-only"}'::jsonb ORDER BY t.n) FROM jsonb_array_elements(content -> 'objects') WITH ORDINALITY AS t(o, n))),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'tennessee-lpm' AND source_record_id = 'TNLP-FINDING-butler-act-vs-1973-law-strategy-shift' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET
  content = jsonb_set(content, '{objects}', (SELECT jsonb_agg((t.o - 'excerptText') || '{"accessTier": "summary-only"}'::jsonb ORDER BY t.n) FROM jsonb_array_elements(content -> 'objects') WITH ORDINALITY AS t(o, n))),
  access_tier = 'summary-only', updated_at = now()
WHERE source_repo = 'us-evolution-education-lpm' AND source_record_id = 'USLP-FINDING-edwards-reasoning-vs-2012-tennessee-law' AND access_tier = 'excerpt-only';

UPDATE curriculum_repository_records SET content = content - 'statementTextEn', updated_at = now()
WHERE record_type = 'institutional-mandate-record' AND access_tier = 'citation-only' AND content ? 'statementTextEn';

DELETE FROM curriculum_repository_records WHERE source_repo = 'diagnostic-test' AND source_record_id IN ('diagnostic-ping-2', 'diagnostic-ping-3');

DO $$
DECLARE left_excerpts integer; left_en integer; left_tests integer;
BEGIN
  SELECT count(*) INTO left_excerpts FROM curriculum_repository_records WHERE source_record_id IN ('FLLP-EVENT-sb2692-hb1483-2008-academic-freedom-act', 'FLLP-EVENT-2024-textbook-climate-content-removal', 'FLLP-EVENT-2026-draft-standards-released-for-comment', 'FLLP-EVENT-2026-listening-tour-armwood-hs', 'PALP-EVENT-dover-curriculum-committee-pushes-balance', 'PALP-EVENT-dover-teachers-refuse-and-disclaimer-first-read', 'PALP-EVENT-dover-2005-election', 'PALP-EVENT-dover-2004-10-18-board-vote', 'PALP-EVENT-dover-2006-01-policy-rescinded', 'PALP-EVENT-kitzmiller-trial', 'PALP-EVENT-dover-2006-02-legal-fees-settlement', 'TNLP-EVENT-aclu-ad-and-scopes-recruitment', 'TNLP-EVENT-butler-act-repealed', 'TNLP-EVENT-tn-1973-equal-time-law-passed', 'TNLP-EVENT-tn-2011-2012-teacher-protection-act-legislative-process', 'TNLP-EVENT-scopes-trial', 'TNLP-EVENT-butler-act-signed', 'TNLP-EVENT-haslam-lets-teacher-protection-act-become-law', 'TNLP-EVENT-bryan-death', 'TNLP-EVENT-butler-act-introduced', 'PALP-FINDING-dover-policy-exceeded-state-standard', 'PALP-FINDING-pa-2002-proposed-vs-final-wording-change', 'TNLP-FINDING-1973-law-vs-2012-law-framing-shift', 'TNLP-FINDING-butler-act-vs-1973-law-strategy-shift', 'USLP-FINDING-edwards-reasoning-vs-2012-tennessee-law') AND access_tier <> 'summary-only';
  SELECT count(*) INTO left_en FROM curriculum_repository_records WHERE access_tier = 'citation-only' AND content ? 'statementTextEn';
  SELECT count(*) INTO left_tests FROM curriculum_repository_records WHERE source_repo = 'diagnostic-test';
  IF left_excerpts <> 0 OR left_en <> 0 OR left_tests <> 0 THEN
    RAISE EXCEPTION 'migration 217: % of 25 excerpt rows still above summary-only, % cite-only rows with statementTextEn, % test rows', left_excerpts, left_en, left_tests;
  END IF;
END $$;
